add("PWH-132553","Lattafa Bade'e Al Oud Oud For Glory Eau De Parfum 100 ml (unisex)","<p>Bade'e Al Oud Oud For Glory od Lattafy je ambrovo-drevitá unisex vôňa z roku 2020. Šafrán, levanduľa a muškátový orech otvárajú, srdce tvorí agarové drevo (oud) s pačuli a základ oud, pačuli a pižmo.</p><ul><li><strong>Hlavné tóny:</strong> šafrán, levanduľa, muškátový orech, oud, pačuli, pižmo</li><li><strong>Kedy ju nosiť:</strong> na jeseň, v zime a večer</li><li><strong>Charakter:</strong> oudová, korenistá a hlboká</li></ul>")
add("PWH-138647","Lattafa Yara Eau De Parfum 100 ml (woman)","<p>Yara od Lattafy je orientálna vanilková dámska vôňa. Otvára ju svieža mandarínka s orchideou, srdce prináša tropické ovocie a gurmánske akordy a základ tvorí vanilka, santal a pižmo.</p><ul><li><strong>Hlavné tóny:</strong> mandarínka, orchidea, heliotrop, tropické ovocie, vanilka, santal, pižmo</li><li><strong>Kedy ju nosiť:</strong> na každý deň, na rande a večer</li><li><strong>Charakter:</strong> sladká, mladistvá a zmyselná</li></ul>")
add("PWH-136375","Lattafa Pride Fakhar Rose Eau De Parfum 100 ml (woman)","<p>Fakhar Rose od Lattafy z rady Pride je sladká kvetinová dámska vôňa. Otvára ju sviežie ovocie s granátovým jablkom, srdce tvorí jazmín, tuberóza a gardénia a vôňa pôsobí pudrovo a romanticky.</p><ul><li><strong>Hlavné tóny:</strong> ovocie, granátové jablko, ľalia, jazmín, tuberóza, gardénia</li><li><strong>Kedy ju nosiť:</strong> na jar a leto, na rande a denné nosenie</li><li><strong>Charakter:</strong> pudrová, kvetinová a romantická</li></ul>")
